<?php
require_once __DIR__ . '/../database/config.php';
require_once __DIR__ . '/../database/config.php';
require_once __DIR__ . '/../process/accessControlHelpers.php';
require_once __DIR__ . '/../common/systemDataHelpers.php';
$pdo=getDB(); requirePageAccess($pdo,'search');
if(!function_exists('e')){function e($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}}
$q=trim((string)($_GET['q']??''));$results=[];$error='';
$push=static function(array $rows,string $module,string $icon)use(&$results){foreach($rows as $r){$r['module']=$module;$r['icon']=$icon;$results[]=$r;}};
if($q!=='' && sys_text_length($q)<2){$error='Enter at least two characters.';}
if($q!=='' && !$error){
 $like='%'.$q.'%';
 try{
  if(userCanAccessPage($pdo,'member_list') && sys_table_exists($pdo,'water_accounts')){
   $s=$pdo->prepare("SELECT pkey,account_number,CONCAT_WS(', ', NULLIF(lastname, ''), NULLIF(firstname, '')) title,CONCAT('Account ',COALESCE(account_number,CAST(pkey AS CHAR)),', ',CASE WHEN status='A' THEN 'Active' ELSE 'Inactive' END) subtitle FROM water_accounts WHERE account_number LIKE ? OR lastname LIKE ? OR firstname LIKE ? OR CAST(pkey AS CHAR) LIKE ? ORDER BY lastname,firstname LIMIT 15");$s->execute([$like,$like,$like,$like]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['href']='member_list.php?search='.rawurlencode((string)($r['account_number']?:$r['pkey']));$r['result_type']='Member';}unset($r);$push($rows,'Members','M');
  }
  if(userCanAccessPage($pdo,'billing_history') && sys_table_exists($pdo,'bill_readings')){
   $s=$pdo->prepare("SELECT br.reading_id,br.global_ref_number,CONCAT_WS(', ', NULLIF(m.lastname, ''), NULLIF(m.firstname, '')) title,CONCAT('Water bill, Ref ',COALESCE(CAST(br.global_ref_number AS CHAR),CAST(br.reading_id AS CHAR)),', ₱',FORMAT(br.amount_due,2)) subtitle FROM bill_readings br JOIN water_accounts m ON m.pkey=br.member_id WHERE CAST(br.reading_id AS CHAR) LIKE ? OR CAST(br.global_ref_number AS CHAR) LIKE ? OR m.account_number LIKE ? OR m.lastname LIKE ? OR m.firstname LIKE ? ORDER BY br.reading_id DESC LIMIT 12");$s->execute([$like,$like,$like,$like,$like]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['href']='billing_history.php?search='.rawurlencode((string)($r['global_ref_number']?:$r['reading_id']));$r['result_type']='Water Bill';}unset($r);$push($rows,'Billing','W');
  }
  if(userCanAccessPage($pdo,'payment_history') && sys_table_exists($pdo,'payment_transactions')){
   $s=$pdo->prepare("SELECT pt.transaction_id,pt.receipt_no,CONCAT_WS(', ', NULLIF(m.lastname, ''), NULLIF(m.firstname, '')) title,CONCAT('Receipt ',pt.receipt_no,', ₱',FORMAT(pt.total_paid,2),', ',DATE_FORMAT(pt.payment_date,'%Y-%m-%d')) subtitle FROM payment_transactions pt JOIN water_accounts m ON m.pkey=pt.member_id WHERE pt.receipt_no LIKE ? OR CAST(pt.transaction_id AS CHAR) LIKE ? OR m.account_number LIKE ? OR m.lastname LIKE ? OR m.firstname LIKE ? ORDER BY pt.transaction_id DESC LIMIT 12");$s->execute([$like,$like,$like,$like,$like]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['href']='payment_history.php?search='.rawurlencode((string)$r['receipt_no']);$r['result_type']='Payment';}unset($r);$push($rows,'Collections','P');
  }
  if(userCanAccessPage($pdo,'one_time_billing') && sys_table_exists($pdo,'one_time_bills')){
   $s=$pdo->prepare("SELECT b.bill_id,b.global_ref_number,CONCAT_WS(', ', NULLIF(m.lastname, ''), NULLIF(m.firstname, '')) title,CONCAT('One-time bill, Ref ',COALESCE(CAST(b.global_ref_number AS CHAR),CAST(b.bill_id AS CHAR)),', ₱',FORMAT(b.total_amount,2)) subtitle FROM one_time_bills b JOIN water_accounts m ON m.pkey=b.member_id WHERE CAST(b.bill_id AS CHAR) LIKE ? OR CAST(b.global_ref_number AS CHAR) LIKE ? OR m.account_number LIKE ? OR m.lastname LIKE ? ORDER BY b.bill_id DESC LIMIT 10");$s->execute([$like,$like,$like,$like]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['href']='one_time_billing.php?search='.rawurlencode((string)($r['global_ref_number']?:$r['bill_id']));$r['result_type']='One-Time Bill';}unset($r);$push($rows,'Billing','O');
  }
  if(userCanAccessPage($pdo,'inventory_purchase') && sys_table_exists($pdo,'inventory_purchases')){
   $s=$pdo->prepare("SELECT purchase_id,purchase_no,purchase_no title,CONCAT('Purchase, ',DATE_FORMAT(purchase_date,'%Y-%m-%d'),', ₱',FORMAT(total_amount,2),', ',status) subtitle FROM inventory_purchases WHERE purchase_no LIKE ? OR remarks LIKE ? ORDER BY purchase_id DESC LIMIT 10");$s->execute([$like,$like]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['href']='inventory_purchase.php?search='.rawurlencode((string)$r['purchase_no']);$r['result_type']='Purchase';}unset($r);$push($rows,'Inventory','I');
  }
  if(userCanAccessPage($pdo,'journal_entry') && sys_table_exists($pdo,'journalvoucher_copy1')){
   $s=$pdo->prepare("SELECT JVID,JVEntryID,JVEntryID title,CONCAT('Journal ',JVID,', ',DATE_FORMAT(JVTransDate,'%Y-%m-%d'),', ',Status) subtitle FROM journalvoucher_copy1 WHERE JVID LIKE ? OR JVEntryID LIKE ? ORDER BY JVTransDate DESC LIMIT 10");$s->execute([$like,$like]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['href']='journal_entry.php?search='.rawurlencode((string)$r['JVEntryID']);$r['result_type']='Journal';}unset($r);$push($rows,'Accounting','J');
  }
 }catch(Throwable $e){$error='Search could not complete: '.$e->getMessage();}
}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Global Search - <?= htmlspecialchars(app_name(), ENT_QUOTES, 'UTF-8') ?></title><link rel="stylesheet" href="../common/fonts.css"><style>*{box-sizing:border-box}body{margin:0;background:#f8f9fb;color:#111827;font-family:Sora,sans-serif}.page{max-width:1050px;margin:auto;padding:32px}.title{font-size:1.55rem;margin:0}.sub{color:#6b7280;font-size:.86rem;margin:5px 0 22px}.search{display:flex;background:#fff;border:1px solid #d1d5db;border-radius:14px;padding:8px;box-shadow:0 8px 30px rgba(0,0,0,.06)}.search input{flex:1;border:0;outline:0;font:inherit;font-size:1rem;padding:10px}.search button{border:0;background:#111827;color:#fff;border-radius:9px;padding:0 20px;font-weight:700}.alert{margin-top:16px;padding:12px;border-radius:10px;background:#fef2f2;color:#b91c1c;border:1px solid #fecaca}.meta{margin:20px 0 10px;color:#6b7280;font-size:.78rem}.results{display:grid;gap:9px}.result{display:flex;gap:13px;align-items:center;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:14px;text-decoration:none;color:#111827}.result:hover{border-color:#111827}.icon{width:38px;height:38px;border-radius:10px;background:#111827;color:#fff;display:grid;place-items:center;font-weight:800}.body{min-width:0;flex:1}.name{font-weight:700}.desc{color:#6b7280;font-size:.78rem;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.tag{font-size:.65rem;font-weight:800;text-transform:uppercase;background:#f3f4f6;padding:5px 8px;border-radius:999px}.empty{background:#fff;border:1px dashed #d1d5db;border-radius:14px;padding:40px;text-align:center;color:#6b7280}@media(max-width:650px){.page{padding:20px 14px}.tag{display:none}}</style></head><body><?php require_once '../common/navbar.php';?><div class="main-content"><main class="page"><h1 class="title">Global Search</h1><p class="sub">Search permitted members, bills, receipts, purchases, and journal references from one page.</p><form class="search" method="get"><input name="q" value="<?=e($q)?>" placeholder="Name, account, receipt, bill, purchase, or journal reference" autofocus><button>Search</button></form><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($q!==''):?><div class="meta"><?=count($results)?> result(s) for “<?=e($q)?>”</div><?php endif;?><div class="results"><?php foreach($results as $r):?><a class="result" href="<?=e($r['href'])?>"><div class="icon"><?=e($r['icon'])?></div><div class="body"><div class="name"><?=e($r['title'])?></div><div class="desc"><?=e($r['subtitle'])?></div></div><span class="tag"><?=e($r['result_type'])?></span></a><?php endforeach;?><?php if($q!==''&&!$results&&!$error):?><div class="empty">No permitted records matched the search.</div><?php elseif($q===''):?><div class="empty">Enter at least two characters to begin.</div><?php endif;?></div></main></div></body></html>
